CoD.ZShareSettings = CoD.ZShareSettings or {}
CoD.ZShareSettings.Locale = ZShareLocaleAdapter.Create( ZShareLocaleCore, ZShareCatalogs,
	function () return Engine, Dvar end )

-- What every visible string goes through. It NEVER returns the key: a key on screen is
-- what the old .str route did when its fastfile was not loaded, and it is the one mistake
-- here that shows up in game rather than in a check. pcall because a renderer must not die
-- because a catalog lookup threw.
CoD.ZShareSettings.Text = function ( key, fallback )
	fallback = type( fallback ) == "string" and fallback or ""
	if type( key ) ~= "string" or key == "" then
		return fallback
	end
	local ok, text = pcall( CoD.ZShareSettings.Locale.Text, key )
	if not ok or type( text ) ~= "string" or text == "" or text == key then
		return fallback
	end
	return text
end

-- The English a key was generated from. A renderer resolves a key only while the text it
-- holds is still this, because a row can be copied and re-worded with its keys still on it:
-- CHANGED's "ZSHARE - TRADE" carries setting.zs_trade, whose translation is "TRADE", and a
-- copy listing one current value carries the source row's whole list of choice keys, so its
-- first key names the source row's FIRST choice. Every Z mod's copy of the shell copies rows
-- that way, so the check belongs where the text is drawn, not where the copy is made.
CoD.ZShareSettings.Source = function ( key )
	if type( key ) ~= "string" then
		return nil
	end
	return ZShareCatalogs["en"][key]
end

-- A pattern with named substitutions, for the composed strings.
CoD.ZShareSettings.Format = function ( key, fallback, values )
	local pattern = CoD.ZShareSettings.Text( key, fallback )
	if type( values ) ~= "table" then
		return pattern
	end
	local ok, text = pcall( CoD.ZShareSettings.Locale.Format, pattern, values )
	if not ok or type( text ) ~= "string" or text == "" then
		return pattern
	end
	return text
end

-- ZShare's words, for any Z mod's renderer that draws them. The shared menu kit's owner-localizer
-- ABI, presentation v1: CoD.ZBundleSettings.Localizers.<owner> = { version = 1, text = ... }.
-- Resolved by identity and English equality, never by position, and anything it does not know
-- comes back exactly as it went in, which is what tells a renderer to try the shell's words next.
local ZShareReverse = {}
for key, english in pairs( ZShareCatalogs["en"] ) do
	if ZShareReverse[english] == nil then
		ZShareReverse[english] = key
	elseif ZShareReverse[english] ~= key then
		ZShareReverse[english] = false
	end
end

CoD.ZShareSettings.Provide = function ( english, context )
	if type( english ) ~= "string" or english == "" then
		return english
	end
	local en = ZShareCatalogs["en"]
	local function fits( key )
		if type( key ) == "string" and en[key] == english then
			return CoD.ZShareSettings.Text( key, english )
		end
		return nil
	end
	local row = type( context ) == "table" and context.row or nil
	local tab = type( context ) == "table" and context.tab or nil
	local found = nil
	if type( row ) == "table" then
		found = fits( row.labelKey ) or fits( row.hintKey ) or fits( row.boundaryKey ) or fits( row.scopeKey )
		if found ~= nil then
			return found
		end
		if type( row.choiceKeys ) == "table" then
			for _, key in ipairs( row.choiceKeys ) do
				found = fits( key )
				if found ~= nil then
					return found
				end
			end
		end
		if type( row.dvar ) == "string" then
			found = fits( "setting." .. row.dvar ) or fits( "hint." .. row.dvar )
			if found ~= nil then
				return found
			end
			if type( row.values ) == "table" then
				for _, value in ipairs( row.values ) do
					found = fits( "choice." .. row.dvar .. "." .. tostring( value ) )
					if found ~= nil then
						return found
					end
				end
			end
		end
	end
	if type( tab ) == "table" then
		found = fits( tab.labelKey ) or fits( tab.hintKey )
		if found == nil and type( tab.id ) == "string" then
			found = fits( "page." .. tab.id ) or fits( "page." .. tab.id .. ".hint" )
		end
		if found ~= nil then
			return found
		end
	end
	local key = ZShareReverse[english]
	if type( key ) == "string" then
		return CoD.ZShareSettings.Text( key, english )
	end
	return english
end

CoD.ZBundleSettings = CoD.ZBundleSettings or {}
CoD.ZBundleSettings.Localizers = CoD.ZBundleSettings.Localizers or {}
CoD.ZBundleSettings.Localizers.zshare = {
	version = 1,
	text = function ( english, context )
		return CoD.ZShareSettings.Provide( english, context )
	end
}
